<main>
  <div id="chat">
    <div class="empty" id="empty">
      <h2>Chat with MyGPT</h2>
      <p>Your locally fine-tuned model. Toggle <b>Use my documents</b> to ground
      answers in your indexed files, with page-aware citations.</p>
    </div>
  </div>
</main>
<footer>
  <div class="composer">
    <textarea id="input" placeholder="Ask MyGPT…  (Enter to send, Shift+Enter for newline)"></textarea>
    <button class="send" id="send">Send</button>
  </div>
  <div class="hint" id="hint"></div>
</footer>

<script>
const chat = document.getElementById('chat');
const input = document.getElementById('input');
const sendBtn = document.getElementById('send');
const ragToggle = document.getElementById('ragToggle');
const ragWrap = document.getElementById('ragToggleWrap');
const statusEl = document.getElementById('status');
const hintEl = document.getElementById('hint');
const empty = document.getElementById('empty');

let history = [];   // [{role, content}]
let busy = false;

// Load backend / RAG status
fetch('/api/info').then(r => r.json()).then(info => {
  statusEl.textContent = info.backend;
  hintEl.textContent = info.rag_available
    ? `RAG ready · ${info.rag_chunks} chunks indexed`
    : 'RAG index not built — run scripts/rag_ingest.py to enable document Q&A';
  if (!info.rag_available) {
    ragToggle.disabled = true;
    ragWrap.style.opacity = .5;
    ragWrap.title = 'Build a RAG index first (scripts/rag_ingest.py)';
  }
}).catch(() => statusEl.textContent = 'offline');

function escapeHtml(s) {
  return s.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
}
// Highlight [1], [2] citation markers
function renderBot(text) {
  return escapeHtml(text).replace(/\[(\d+)\]/g, '<span class="cite">[$1]</span>');
}

function addMsg(role, text) {
  empty.style.display = 'none';
  const div = document.createElement('div');
  div.className = 'msg ' + (role === 'user' ? 'user' : 'bot');
  div.innerHTML = `<div class="who">${role === 'user' ? 'You' : 'MyGPT'}</div>` +
                  (role === 'user' ? escapeHtml(text) : renderBot(text));
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight;
  return div;
}

function addSources(sources) {
  if (!sources || !sources.length) return;
  const div = document.createElement('div');
  div.className = 'sources';
  div.innerHTML = '<b>Sources</b>' + sources.map(s =>
    `<div class="src-item"><span class="lbl">[${s.n}] ${escapeHtml(s.label)}</span> ` +
    `<span class="score">· ${s.score}</span><br>${escapeHtml(s.preview)}…</div>`
  ).join('');
  chat.appendChild(div);
  chat.scrollTop = chat.scrollHeight;
}

async function send() {
  const message = input.value.trim();
  if (!message || busy) return;
  busy = true; sendBtn.disabled = true;
  addMsg('user', message);
  input.value = '';

  const typing = addMsg('bot', '…');
  typing.classList.add('typing');

  try {
    const res = await fetch('/api/chat', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({
        message, history, use_rag: ragToggle.checked,
      }),
    });
    const data = await res.json();
    typing.remove();
    addMsg('bot', data.reply || '(no response)');
    if (ragToggle.checked) addSources(data.sources);
    history.push({role: 'user', content: message});
    history.push({role: 'assistant', content: data.reply});
  } catch (e) {
    typing.remove();
    addMsg('bot', '⚠️ Error contacting the server: ' + e.message);
  } finally {
    busy = false; sendBtn.disabled = false; input.focus();
  }
}

sendBtn.addEventListener('click', send);
input.addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); }
});
input.focus();
</script>
</body>
</html>
